package glitch

import data.glitch_lib
import future.keywords.every

# Weak cryptographic algorithms and hash functions
weak_crypto_algorithms := {
    "des", "3des", "tripledes", "rc2", "rc4", "rc5", "rc6",
    "md5", "md5_crypt", "sha1", "sha-1",
    "blowfish", "idea", "skipjack", "tea", "xtea",
    "aes-128", "aes128", "aes_128",
    "rsa_with_aes_128"
}

# Crypto-related attribute names (general patterns)
crypto_attr_patterns := {
    "encrypt", "cipher", "hash", "algorithm", "crypto",
    "checksum", "digest", "key_type", "key_spec",
    "cipher_suite", "cipher_suites", "kms_key_id",
    "auth_method"
}

# Check if string contains weak crypto algorithm
has_weak_crypto(value_str) {
    lower_val := lower(value_str)
    algo := weak_crypto_algorithms[_]
    regex.match(sprintf(".*%s.*", [algo]), lower_val)
}

# Check if attribute name is crypto-related
is_crypto_attr(name) {
    lower_name := lower(name)
    pattern := crypto_attr_patterns[_]
    regex.match(sprintf(".*%s.*", [pattern]), lower_name)
}

# Extract all string values from any node structure recursively
extract_strings(node, results) {
    node.ir_type == "String"
    results := {node}
}

extract_strings(node, results) {
    node.ir_type == "Array"
    child := node.value[_]
    child_results := extract_strings_set(child)
