}

extract_strings(node, results) {
    node.ir_type == "Hash"
    pair := node.value[_]
    key_results := extract_strings_set(pair.key)
    val_results := extract_strings_set(pair.value)
    results := key_results | val_results
}

extract_strings(node, results) {
    node.ir_type == "Access"
    left_results := extract_strings_set(node.left)
    right_results := extract_strings_set(node.right)
    results := left_results | right_results
}

extract_strings(node, results) {
    node.ir_type == "FunctionCall"
    name_results := {{"ir_type": "String", "line": node.line, "code": node.name, "value": node.name}}
    arg_results := {r | arg := node.args[_]; r := extract_strings_set(arg)[_]}
    results := name_results | arg_results
}

extract_strings(node, results) {
    node.ir_type == "MethodCall"
    recv_results := extract_strings_set(node.receiver)
